  "Elevação de Panturrilha Sentado (Máquina)":{group:"Panturrilha",secondary:[],type:"Isolado",equipment:"Máquina",muscles:["Sóleo","Gastrocnêmio"],instructions:["Sentado, joelhos sob o apoio, pés na borda da plataforma.","Eleve os calcanhares o máximo possível.","Segure no topo e desça para o alongamento completo."],tips:"Sentado isola melhor o sóleo que tende a ser negligenciado."},
  // BRAÇOS
  "Rosca Direta na Barra W":{group:"Biceps",secondary:["Antebraço"],type:"Isolado",equipment:"Barra W",muscles:["Bíceps braquial","Braquial"],instructions:["Em pé, barra W com pegada supinada na largura dos ombros.","Flexione os cotovelos trazendo a barra até os ombros.","Contraia os bíceps no topo.","Desça controlado até extensão completa."],tips:"Mantenha os cotovelos fixos ao lado do corpo."},
  "Rosca Scott (Barra)":{group:"Biceps",secondary:[],type:"Isolado",equipment:"Banco Scott + Barra",muscles:["Bíceps braquial (porção longa)"],instructions:["Apoie os tríceps no banco inclinado do Scott.","Pegada supinada, cotovelos apoiados.","Flexione trazendo a barra em direção ao rosto.","Desça controlado até extensão quase completa."],tips:"O apoio elimina o balanço — foco total no bíceps."},
  "Rosca Inclinada (Halter)":{group:"Biceps",secondary:[],type:"Isolado",equipment:"Halter + Banco",muscles:["Bíceps braquial (porção longa)","Braquial"],instructions:["Banco inclinado a 45-60°. Halteres pendurados ao lado do corpo.","Flexione um braço de cada vez ou alternado.","Cotovelo fica atrás do corpo ao longo de todo o movimento."],tips:"O ângulo inclinado alonga o bíceps no início dando um ROM maior."},
  "Rosca Martelo (Halter)":{group:"Biceps",secondary:["Antebraço"],type:"Isolado",equipment:"Halter",muscles:["Braquiorradial","Bíceps braquial","Braquial"],instructions:["Em pé, halteres com pegada neutra (palmas para dentro).","Flexione os cotovelos mantendo a pegada neutra.","Contraia no topo e desça controlado."],tips:"A pegada neutra ativa mais o braquiorradial e braquial."},
