              {rangeDelta!==0&&<div style={{fontSize:11,fontWeight:700,color:rangeDelta>0?C.mint:C.coral,marginTop:2}}>{rangeDelta>0?"↑":"↓"} {Math.abs(rangeDelta)}% vs anterior</div>}
