function VolumeSpiderChart({volumeByGroup,size=260}){
  const order=["Peito","Costas","Pernas","Ombros","Glúteos","Core"];
  const maxVol=Math.max(...order.map(g=>volumeByGroup[g]||0),1);
  const data=order.map(g=>({g,pct:Math.round(((volumeByGroup[g]||0)/maxVol)*100),color:GC[g]||C.blueXL,vol:Math.round(volumeByGroup[g]||0)}));
  const N=order.length,CX=size/2,CY=size/2,R=size*0.33,LD=size*0.44;
  const ang=(i)=>(i/N)*Math.PI*2+(-150*Math.PI/180);
  const ox=(i)=>CX+R*Math.cos(ang(i));
  const oy=(i)=>CY+R*Math.sin(ang(i));
  const vx=(m,i)=>CX+R*(m.pct/100)*Math.cos(ang(i));
  const vy=(m,i)=>CY+R*(m.pct/100)*Math.sin(ang(i));
  const rings=[0.25,0.5,0.75,1];
  const axes=data.map((_,i)=>i);
  const dataStr=data.map((m,i)=>vx(m,i)+","+vy(m,i)).join(" ");
  return(
    <svg width={size} height={size} viewBox={"0 0 "+size+" "+size} style={{display:"block",margin:"0 auto"}}>
      {rings.map(lv=>(
        <polygon key={lv} points={axes.map(i=>(CX+(ox(i)-CX)*lv)+","+(CY+(oy(i)-CY)*lv)).join(" ")} fill="none" stroke="rgba(255,255,255,0.07)" strokeWidth="1"/>
      ))}
      {axes.map(i=>(
        <line key={i} x1={CX} y1={CY} x2={ox(i)} y2={oy(i)} stroke="rgba(255,255,255,0.07)" strokeWidth="1"/>
      ))}
      <polygon points={dataStr} fill={C.blueXL+"2A"} stroke={C.blueXL} strokeWidth="2" strokeLinejoin="round"/>
      {data.map((m,i)=>(
        <circle key={i} cx={vx(m,i)} cy={vy(m,i)} r="4" fill={m.color} stroke="rgba(0,0,0,0.5)" strokeWidth="1"/>
      ))}
      {data.map((m,i)=>{
        const lx=CX+LD*Math.cos(ang(i));
        const ly=CY+LD*Math.sin(ang(i));
        const anchor=lx<CX-4?"start":lx>CX+4?"end":"middle";
        return(
          <g key={i}>
            <text x={lx} y={ly-5} textAnchor={anchor} dominantBaseline="middle" fontSize="10" fontWeight="700" fill={m.color}>{m.g}</text>
            <text x={lx} y={ly+8} textAnchor={anchor} dominantBaseline="middle" fontSize="9" fill={m.color+"BB"}>{m.vol>0?m.vol+"kg":"—"}</text>
          </g>
        );
      })}
    </svg>
  );
}

// Map from muscle group → image file
const MUSCLE_IMG = {
  "Peito":       "/body-peito.png",
  "Costas":      "/body-costas.png",
  "Ombros":      "/body-ombros.png",
  "Pernas":      "/body-pernas.png",
  "Braços":      "/body-biceps.png",
  "Core":        "/body-core.png",
  "Glúteos":     "/body-gluteos.png",
  "Panturrilha": "/body-panturrilha.png",
};

// Priority order — which muscle to show if multiple are active
const MUSCLE_PRIORITY = ["Peito","Costas","Pernas","Ombros","Braços","Core","Glúteos","Panturrilha"];

function BodyDiagram({muscleHeat,width=320,savedCount=0}){
  const H = Math.round(width * (1024/1536));

  // Seleciona imagem baseada nos treinos DA SEMANA ATUAL (dom a sáb)
  const imgSrc = useMemo(()=>{
    const allSessions = getAllSessions();
    const now = new Date();
    const sunday = new Date(now);
    sunday.setDate(now.getDate() - now.getDay());
    sunday.setHours(0,0,0,0);
    const weekStart = sunday.toISOString().slice(0,10);

    const thisWeek = allSessions.filter(s => s.date >= weekStart);
    const names = thisWeek.map(s => (s.name||"").toLowerCase());
    const has = (kw) => names.some(n => n.includes(kw));

    const hasPush  = has("push");
    const hasPull  = has("pull") || has("bíceps") || has("biceps");
    const hasLegs  = has("legs") || has("leg") || has("pernas");
    const hasUpper = has("upper");

    // Acumulativo — mais treinos na semana = mais músculos acesos
    if(hasPush && hasPull && hasLegs) return "/body-semana-atual.png";
    if(hasPush && hasPull)            return "/body-push-pull.png";
    if(hasPush && hasLegs)            return "/body-push-legs.png";
    if(hasPull && hasLegs)            return "/body-pull-legs.png";
    if(hasUpper && hasLegs)           return "/body-upper-legs.png";
    if(hasPush)                       return "/body-push.png";
    if(hasPull)                       return "/body-pull.png";
    if(hasLegs)                       return "/body-legs.png";
    if(hasUpper)                      return "/body-upper.png";
    return "/body-rest.png";
  },[savedCount]);

  return(
    <div style={{width, height:H, margin:"0 auto", position:"relative", borderRadius:12, overflow:"hidden", background:"transparent"}}>
      <img
        src={imgSrc}
        alt="Mapa muscular"
        style={{width:"100%",height:"100%",objectFit:"contain",display:"block"}}
      />
    </div>
  );
}



