// MEDIÇÕES SCREEN — track body measurements over time
// ══════════════════════════════════════════════════════════════
function MedicoesScreen({onNavigate}){
  const scrollRef=useRef(null);
  useLayoutEffect(()=>{if(scrollRef.current)scrollRef.current.scrollTop=0;},[]);
  const ALL_FIELDS=["Peso","Braço D","Braço E","Peito","Cintura","Coxa D","Panturrilha D"];
  const[sel,setSel]=useState("Peso");
  const[range,setRange]=useState("3m");
  const[showAdd,setShowAdd]=useState(false);
  const[draft,setDraft]=useState({});
  const[history,setHistory]=useState(loadMeasureHistory);

  useEffect(()=>{
    document.body.classList.add("hide-carbon-header");
    return()=>document.body.classList.remove("hide-carbon-header");
  },[]);

  // Build chart data for selected field
  const fieldData=history
    .filter(h=>h[sel]!=null)
    .map(h=>({date:h.date,v:parseFloat(h[sel])}))
    .sort((a,b)=>a.date.localeCompare(b.date));

  const nPts={all:fieldData.length,"1a":24,"3m":12,"1m":6}[range]||12;
  const chartPts=fieldData.slice(-nPts);
  const maxY=Math.max(...chartPts.map(d=>d.v),0.01);
  const rawMin=Math.min(...chartPts.map(d=>d.v));
  // Eixo Y começa um pouco abaixo do mínimo para o gráfico não ficar achatado
  const margin=(maxY-rawMin)*0.3||maxY*0.05||1;
  const minY=Math.max(0,rawMin-margin);
  const W=400,H=160,PAD=10,LPAD=44;
  const px=(i)=>chartPts.length>1?i*(W-LPAD-PAD)/(chartPts.length-1)+LPAD:W/2;
  const py=(v)=>H-PAD*2-((v-minY)/(maxY-minY||1))*(H-PAD*3);
  const last=chartPts[chartPts.length-1];
  const unit=sel==="Peso"?"kg":"cm";

  // Comparativo: média do período atual vs média do período anterior
  const now=new Date();
  const dayMs=86400000;
  const periodDays={"1m":30,"3m":91,"1a":365,"all":9999}[range]||91;
  const cutoff=new Date(now-periodDays*dayMs).toISOString().slice(0,10);
  const prevCutoff=new Date(now-periodDays*2*dayMs).toISOString().slice(0,10);
  const periodPts=fieldData.filter(d=>d.date>=cutoff);
  const prevPts=fieldData.filter(d=>d.date>=prevCutoff&&d.date<cutoff);
  const avg=(arr)=>arr.length>0?arr.reduce((a,d)=>a+d.v,0)/arr.length:null;
  const periodAvg=avg(periodPts);
  const prevAvg=avg(prevPts);
  const delta=periodAvg!=null&&prevAvg!=null?+(periodAvg-prevAvg).toFixed(2):null;
  const showLabel=(i)=>chartPts.length<=6||i===0||i===chartPts.length-1||i===Math.floor(chartPts.length/2);

  async function saveEntry(){
    const today=new Date().toISOString().slice(0,10);
    const newFields={};
    ALL_FIELDS.forEach(f=>{if(draft[f]&&!isNaN(parseFloat(draft[f])))newFields[f]=parseFloat(draft[f]);});
    if(!Object.keys(newFields).length)return;
    const existing=history.findIndex(h=>h.date===today);
    let newH=[...history];
    if(existing>=0) newH[existing]={...newH[existing],...newFields,date:today};
    else newH=[...newH,{date:today,...newFields}];
    newH=newH.sort((a,b)=>a.date.localeCompare(b.date));
    setHistory(newH);
    await saveMeasureHistory(newH);
    setDraft({});
    setShowAdd(false);
  }

  const gc=C.blueXL;

  return(
    <div ref={scrollRef} data-screen-container="1" className="screen-root" style={{background:"#080A0E",minHeight:"100dvh",paddingTop:0,overflowY:"auto",paddingBottom:120}}>
      {/* Header */}
      <div style={{position:"sticky",top:0,zIndex:9001,background:"rgba(6,8,12,0.98)",backdropFilter:"blur(20px)",paddingTop:8}}>
        <div style={{padding:"10px 16px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <div style={{display:"flex",alignItems:"center",gap:12}}>
            <button onClick={()=>onNavigate("home")} style={{width:34,height:34,borderRadius:"50%",background:C.card,border:"1px solid "+C.border,color:C.sub,fontSize:20,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>‹</button>
            <div style={{fontSize:20,fontWeight:900,color:C.text,letterSpacing:"-0.5px"}}>Medições</div>
          </div>
          <button onClick={()=>setShowAdd(true)} style={{width:34,height:34,borderRadius:"50%",background:C.blueXL,border:"none",color:"#fff",fontSize:20,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>+</button>
        </div>
      </div>

      <div style={{padding:"16px 16px 0"}}>
        {/* Main chart card */}
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:16,marginBottom:16}}>
          {/* KPI */}
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:4}}>
            <div>
              {last
                ? <><div style={{fontSize:36,fontWeight:900,color:C.text,letterSpacing:"-2px",lineHeight:1}}>{last.v}<span style={{fontSize:14,color:C.sub,marginLeft:4}}>{unit}</span></div>
                    <div style={{display:"flex",alignItems:"center",gap:8,marginTop:4}}>
                      <span style={{fontSize:11,color:C.blueXL}}>{new Date(last.date+"T12:00:00").toLocaleDateString("pt-BR",{day:"numeric",month:"short"})}</span>
                      {delta!==null&&<span style={{fontSize:12,fontWeight:700,color:delta<=0?C.mint:C.coral}}>{delta>0?"+":""}{delta}{unit}</span>}
                    </div></>
                : <div style={{fontSize:14,color:C.muted}}>Sem dados</div>
              }
            </div>
            <div style={{display:"flex",gap:4}}>
              {[{k:"1m",l:"1M"},{k:"3m",l:"3M"},{k:"1a",l:"Ano"},{k:"all",l:"Tudo"}].map(r=>(
                <button key={r.k} onClick={()=>setRange(r.k)} style={{padding:"4px 8px",borderRadius:99,fontSize:10,fontWeight:700,cursor:"pointer",background:range===r.k?C.blueXL:"transparent",border:"1px solid "+(range===r.k?C.blueXL:C.border),color:range===r.k?"#fff":C.sub}}>{r.l}</button>
              ))}
            </div>
          </div>

          {/* Bar chart */}
          {chartPts.length>0&&(()=>{
            const barMax=Math.max(...chartPts.map(d=>d.v),0.01);
            const barMin=Math.min(...chartPts.map(d=>d.v));
            const barRange=barMax-barMin||1;
            const yTicks=[barMin,barMin+barRange*0.5,barMax].map(v=>Math.round(v*10)/10);
            const[selBar,setSelBar]=useState(null);
            const chartH=110;
            return(
              <div style={{marginTop:14,marginBottom:6}}>
                {/* Tooltip */}
                {selBar!=null&&chartPts[selBar]&&(
                  <div style={{background:"rgba(0,0,0,0.9)",border:"1px solid "+C.blueXL+"66",borderRadius:8,padding:"5px 10px",marginBottom:8,display:"flex",justifyContent:"space-between"}}>
                    <span style={{fontSize:11,color:C.muted}}>{new Date(chartPts[selBar].date+"T12:00:00").toLocaleDateString("pt-BR",{day:"numeric",month:"short"})}</span>
                    <span style={{fontSize:14,fontWeight:800,color:C.blueXL}}>{chartPts[selBar].v}{unit}</span>
                  </div>
                )}
                <div style={{display:"flex",gap:6}}>
                  {/* Eixo Y */}
                  <div style={{display:"flex",flexDirection:"column",justifyContent:"space-between",alignItems:"flex-end",height:chartH+16,paddingBottom:16,flexShrink:0,width:36}}>
                    {[yTicks[2],yTicks[1],yTicks[0]].map((v,i)=>(
                      <span key={i} style={{fontSize:8,color:C.muted,lineHeight:1}}>{v}{unit}</span>
                    ))}
                  </div>
                  <div style={{flex:1}}>
                    <div style={{position:"relative",height:chartH}}>
                      <div style={{position:"absolute",inset:0,display:"flex",gap:2,alignItems:"flex-end"}}>
                        {chartPts.map((d,i)=>{
                          const pct=(d.v-barMin)/(barRange||1);
                          const isLast=i===chartPts.length-1;
                          const isSel=selBar===i;
                          const bH=Math.max(pct*chartH,3);
                          return(
                            <div key={i} onClick={()=>setSelBar(isSel?null:i)}
                              style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"flex-end",height:"100%",cursor:"pointer",position:"relative"}}>
                              {isSel&&(
                                <div style={{position:"absolute",bottom:bH+4,left:"50%",transform:"translateX(-50%)",background:"rgba(0,0,0,0.9)",border:"1px solid "+C.blueXL,borderRadius:6,padding:"2px 5px",whiteSpace:"nowrap",zIndex:10,pointerEvents:"none"}}>
                                  <div style={{fontSize:10,fontWeight:800,color:C.blueXL}}>{d.v}{unit}</div>
                                </div>
                              )}
                              <div style={{width:"100%",height:bH,background:isSel?C.blueXL:(isLast?C.blueXL+"CC":C.blueXL+"44"),borderRadius:"3px 3px 0 0",transition:"all 0.15s"}}/>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                    <div style={{display:"flex",justifyContent:"space-between",marginTop:4}}>
                      <span style={{fontSize:8,color:C.muted}}>{new Date(chartPts[0].date+"T12:00:00").toLocaleDateString("pt-BR",{day:"2-digit",month:"short"})}</span>
                      {chartPts.length>2&&<span style={{fontSize:8,color:C.muted}}>{new Date(chartPts[Math.floor(chartPts.length/2)].date+"T12:00:00").toLocaleDateString("pt-BR",{day:"2-digit",month:"short"})}</span>}
                      <span style={{fontSize:8,color:C.muted}}>{new Date(chartPts[chartPts.length-1].date+"T12:00:00").toLocaleDateString("pt-BR",{day:"2-digit",month:"short"})}</span>
                    </div>
                  </div>
                </div>
              </div>
            );
          })()}

          {/* Field selector */}
          <div style={{display:"flex",gap:6,overflowX:"auto",marginTop:10,paddingBottom:2}}>
            {ALL_FIELDS.map(f=>(
              <button key={f} onClick={()=>setSel(f)} style={{padding:"6px 14px",borderRadius:99,flexShrink:0,cursor:"pointer",background:sel===f?C.blueXL+"33":"transparent",border:"1px solid "+(sel===f?C.blueXL:C.border),color:sel===f?C.blueXL:C.sub,fontSize:12,fontWeight:sel===f?700:500,whiteSpace:"nowrap"}}>{f}</button>
            ))}
          </div>
        </div>

        {/* History list */}
        <div style={{fontSize:11,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:10}}>Histórico de {sel}</div>
        {[...fieldData].reverse().map((d,i)=>(
          <div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"14px 0",borderBottom:"1px solid "+C.border+"44"}}>
            <div style={{fontSize:14,color:C.sub}}>{new Date(d.date+"T12:00:00").toLocaleDateString("pt-BR",{day:"numeric",month:"short"})}</div>
            <div style={{fontSize:16,fontWeight:700,color:C.text}}>{d.v}{sel==="Peso"?"kg":"cm"}</div>
          </div>
        ))}
        {fieldData.length===0&&<div style={{textAlign:"center",padding:32,color:C.muted,fontSize:13}}>Nenhum dado para {sel}</div>}
      </div>

      {/* Add modal */}
      {showAdd&&(
        <div style={{position:"fixed",inset:0,zIndex:900,background:"rgba(0,0,0,0.75)",backdropFilter:"blur(8px)",display:"flex",alignItems:"flex-end",justifyContent:"center"}}>
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:"20px 20px 0 0",padding:"24px 20px calc(40px + env(safe-area-inset-bottom,0px))",width:"100%",maxWidth:500}}>
            <div style={{fontSize:16,fontWeight:800,color:C.text,marginBottom:4}}>Atualizar Medições</div>
            <div style={{fontSize:11,color:C.sub,marginBottom:16}}>Deixe em branco para não alterar</div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:16}}>
              {ALL_FIELDS.map(f=>(
                <div key={f}>
                  <div style={{fontSize:10,color:C.sub,fontWeight:600,marginBottom:4}}>{f.toUpperCase()} ({f==="Peso"?"kg":"cm"})</div>
                  <input value={draft[f]||""} onChange={e=>setDraft(d=>({...d,[f]:e.target.value}))} type="number" step="0.1" placeholder="—" style={{width:"100%",boxSizing:"border-box",background:C.surface,border:"1px solid "+C.border,borderRadius:10,padding:"10px 12px",fontSize:16,fontWeight:700,color:C.text,outline:"none"}}/>
                </div>
              ))}
            </div>
            <div style={{display:"flex",gap:10}}>
              <button onClick={()=>{setShowAdd(false);setDraft({});}} style={{flex:1,padding:"13px",borderRadius:12,background:C.surface,border:"1px solid "+C.border,color:C.sub,fontWeight:700,cursor:"pointer",fontSize:13}}>Cancelar</button>
              <button onClick={saveEntry} style={{flex:1,padding:"13px",borderRadius:12,background:C.grad,border:"none",color:"#fff",fontWeight:800,cursor:"pointer",fontSize:13}}>Salvar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
// CALENDÁRIO FULL SCREEN — 3 views: Mês, Ano, Plurianual
// ══════════════════════════════════════════════════════════════
function CalendarioFullScreen({onNavigate}){
  const[view,setView]=useState("mes");
  const[selDetail,setSelDetail]=useState(null);
  const workoutDates=useMemo(()=>{const s=new Set();getAllSessions().forEach(f=>{if(f.date)s.add(f.date);});return s;},[]);
  const todayStr=new Date().toISOString().slice(0,10);
  const allSessions=getAllSessions();

  useEffect(()=>{
    document.body.classList.add("hide-carbon-header");
    return()=>document.body.classList.remove("hide-carbon-header");
  },[]);

  // Session detail overlay
  if(selDetail){
    const daySessions=allSessions.filter(s=>s.date===selDetail);
    return(
      <div style={{position:"fixed",inset:0,zIndex:900,background:"#080A0E",overflowY:"auto",paddingTop:8}}>
        <div style={{padding:"14px 16px",display:"flex",alignItems:"center",gap:12}}>
          <button onClick={()=>setSelDetail(null)} style={{width:34,height:34,borderRadius:"50%",background:C.card,border:"1px solid "+C.border,color:C.sub,fontSize:20,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>‹</button>
          <div style={{fontSize:16,fontWeight:700,color:C.text}}>{new Date(selDetail+"T12:00:00").toLocaleDateString("pt-BR",{weekday:"long",day:"numeric",month:"long"})}</div>
        </div>
        <div style={{padding:"0 16px 80px"}}>
          {daySessions.length===0?<div style={{textAlign:"center",padding:40,color:C.muted}}>Sem treino neste dia</div>:
          daySessions.map((s,i)=>(
            <div key={i} style={{background:C.card,border:"1px solid "+C.border,borderRadius:14,padding:"14px 16px",marginBottom:10}}>
              <div style={{fontSize:15,fontWeight:800,color:C.text,marginBottom:6}}>{s.name||"Treino"}</div>
              <div style={{display:"flex",gap:12,marginBottom:8}}>
                <span style={{fontSize:12,color:C.sub}}>{s.duration?s.duration+"min":"—"}</span>
                <span style={{fontSize:12,color:C.sub}}>{s.totalVol?.toFixed(1)}t</span>
                <span style={{fontSize:12,color:C.sub}}>{s.totalSets} séries</span>
              </div>
              {s.exercises?.map((ex,j)=><div key={j} style={{fontSize:12,color:C.muted,paddingVertical:2}}>{ex.name} · {ex.sets} séries</div>)}
            </div>
          ))}
        </div>
      </div>
    );
  }

  // MÊS view — scrollable months
  const mesScrollRef=useRef(null);
  const renderMes=()=>{
    const now=new Date();
    // Começa em março de 2026 (primeiro mês com registros)
    const FIRST=new Date(2026,2,1); // março 2026
    const months=[];
    let cur=new Date(FIRST);
    while(cur<=new Date(now.getFullYear(),now.getMonth(),1)){
      months.push(new Date(cur));
      cur.setMonth(cur.getMonth()+1);
    }
    return(
      <div
        ref={el=>{
          if(el&&!el._scrolled){
            el._scrolled=true;
            // Rola para mostrar os últimos 2 meses (penúltimo mês visível)
            setTimeout(()=>{
              const items=el.querySelectorAll("[data-month]");
              if(items.length>=2){
                items[items.length-2].scrollIntoView({block:"start"});
              }
            },50);
          }
        }}
        style={{flex:1,overflowY:"auto",padding:"0 16px 100px"}}
      >
        {months.map((monthStart,mi)=>{
          const y=monthStart.getFullYear(),m=monthStart.getMonth();
          const daysInMonth=new Date(y,m+1,0).getDate();
          const firstDay=monthStart.getDay();
          const cells=[];
          for(let i=0;i<firstDay;i++) cells.push(null);
          for(let d=1;d<=daysInMonth;d++) cells.push(d);
          const monthLabel=monthStart.toLocaleDateString("pt-BR",{month:"long",year:"numeric"});
          const monthSessions=allSessions.filter(s=>{
            if(!s.date) return false;
            const sd=new Date(s.date+"T12:00:00");
            return sd.getFullYear()===y&&sd.getMonth()===m;
          });
          return(
            <div key={mi} data-month={`${y}-${m}`} style={{marginBottom:24}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
                <div style={{fontSize:16,fontWeight:800,color:C.text,textTransform:"capitalize"}}>{monthLabel}</div>
                <div style={{fontSize:11,color:C.sub}}>{monthSessions.length} treinos</div>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:1,marginBottom:4}}>
                {["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"].map(d=><div key={d} style={{textAlign:"center",fontSize:9,color:C.muted,padding:"3px 0"}}>{d}</div>)}
              </div>
              <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:2}}>
                {cells.map((d,i)=>{
                  if(!d) return <div key={i}/>;
                  const ds=`${y}-${String(m+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`;
                  const isToday=ds===todayStr;
                  const hasW=workoutDates.has(ds);
                  const daySess=allSessions.filter(s=>s.date===ds);
                  return(
                    <div key={i} onClick={()=>hasW&&setSelDetail(ds)} style={{aspectRatio:"1",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",borderRadius:8,background:hasW?"rgba(59,130,246,0.2)":isToday?"rgba(59,130,246,0.1)":"rgba(255,255,255,0.02)",border:"1px solid "+(hasW?"rgba(59,130,246,0.5)":isToday?"rgba(59,130,246,0.3)":"transparent"),cursor:hasW?"pointer":"default"}}>
                      <span style={{fontSize:11,fontWeight:hasW||isToday?700:400,color:hasW?C.blueXL:isToday?C.blueXL:C.muted}}>{d}</span>
                      {hasW&&daySess[0]&&<span style={{fontSize:7,color:C.blueXL,lineHeight:1,textAlign:"center",overflow:"hidden",maxWidth:"100%",padding:"0 1px"}}>{daySess[0].name?.split("—")[1]?.trim().slice(0,4)||""}</span>}
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  // ANO view — mini month grids
  const renderAno=()=>{
    const now=new Date();
    const y=now.getFullYear();
    const months=Array.from({length:12},(_,m)=>m);
    return(
      <div style={{padding:"0 16px 100px"}}>
        <div style={{fontSize:22,fontWeight:900,color:C.text,marginBottom:16}}>{y}</div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:12}}>
          {months.map(m=>{
            const daysInMonth=new Date(y,m+1,0).getDate();
            const firstDay=new Date(y,m,1).getDay();
            const cells=[];
            for(let i=0;i<firstDay;i++) cells.push(null);
            for(let d=1;d<=daysInMonth;d++) cells.push(d);
            const mLabel=new Date(y,m,1).toLocaleDateString("pt-BR",{month:"short"});
            return(
              <div key={m}>
                <div style={{fontSize:11,fontWeight:700,color:C.sub,marginBottom:4,textTransform:"capitalize"}}>{mLabel}</div>
                <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:1}}>
                  {cells.map((d,i)=>{
                    if(!d) return <div key={i} style={{aspectRatio:"1"}}/>;
                    const ds=`${y}-${String(m+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`;
                    const hasW=workoutDates.has(ds);
                    const isToday=ds===todayStr;
                    return <div key={i} style={{aspectRatio:"1",borderRadius:2,background:hasW?"#3B82F6":isToday?"#1E40AF":"rgba(255,255,255,0.06)"}}/>;
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  // PLURIANUAL view — GitHub-style heatmap
  const renderPlurianual=()=>{
    const now=new Date();
    const years=[now.getFullYear()-1,now.getFullYear()];
    return(
      <div style={{padding:"0 16px 100px"}}>
        {years.map(y=>{
          const months=Array.from({length:12},(_,m)=>m);
          return(
            <div key={y} style={{marginBottom:24}}>
              <div style={{fontSize:16,fontWeight:800,color:C.text,marginBottom:8}}>{y}</div>
              <div style={{display:"flex",gap:2,alignItems:"flex-start"}}>
                <div style={{display:"flex",flexDirection:"column",gap:1,marginRight:4}}>
                  {["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"].map((m,i)=>(
                    <div key={i} style={{fontSize:8,color:C.muted,height:10,display:"flex",alignItems:"center"}}>{m}</div>
                  ))}
                </div>
                <div style={{flex:1}}>
                  <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:1}}>
                    {months.map(m=>{
                      const daysInMonth=new Date(y,m+1,0).getDate();
                      return Array.from({length:daysInMonth},(_,di)=>{
                        const d=di+1;
                        const ds=`${y}-${String(m+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`;
                        const hasW=workoutDates.has(ds);
                        const isToday=ds===todayStr;
                        return <div key={ds} style={{aspectRatio:"1",borderRadius:1,background:hasW?"#3B82F6":isToday?"#1E3A8A":"rgba(255,255,255,0.05)"}}/>;
                      });
                    })}
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return(
    <div data-screen-container="1" className="screen-root" style={{background:"#080A0E",height:"100dvh",display:"flex",flexDirection:"column",paddingTop:0,overflow:"hidden"}}>
      {/* Header fixo */}
      <div style={{flexShrink:0,background:"rgba(6,8,12,0.98)",backdropFilter:"blur(20px)",paddingTop:8,zIndex:50}}>
        <div style={{padding:"10px 16px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <div style={{display:"flex",alignItems:"center",gap:12}}>
            <button onClick={()=>onNavigate("home")} style={{width:34,height:34,borderRadius:"50%",background:C.card,border:"1px solid "+C.border,color:C.sub,fontSize:20,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>‹</button>
            <div style={{fontSize:16,fontWeight:700,color:C.text}}>Calendário</div>
          </div>
          <div style={{display:"flex",background:C.card,borderRadius:10,padding:2,border:"1px solid "+C.border}}>
            {[{k:"mes",l:"Mês"},{k:"ano",l:"Ano"},{k:"plurianual",l:"Plurianual"}].map(v=>(
              <button key={v.k} onClick={()=>setView(v.k)} style={{padding:"5px 10px",borderRadius:8,border:"none",cursor:"pointer",fontSize:11,fontWeight:700,background:view===v.k?"rgba(255,255,255,0.12)":"transparent",color:view===v.k?C.text:C.muted}}>{v.l}</button>
            ))}
          </div>
        </div>
        {/* Cards de streak — fixos abaixo do header */}
        {view==="mes"&&<div style={{display:"flex",gap:8,padding:"0 16px 12px"}}>
          <div style={{flex:1,background:C.card,border:"1px solid "+C.border,borderRadius:12,padding:"10px 14px",display:"flex",alignItems:"center",gap:8}}>
            <span style={{fontSize:18}}>🔥️</span>
            <div>
              <div style={{fontSize:16,fontWeight:900,color:C.text}}>{(()=>{let s=0;const d=new Date();while(true){const ds=d.toISOString().slice(0,10);if(!workoutDates.has(ds)&&ds!==todayStr)break;if(workoutDates.has(ds))s++;d.setDate(d.getDate()-1);if(s>365)break;}return s;})()}</div>
              <div style={{fontSize:9,color:C.sub}}>dias seguidos</div>
            </div>
          </div>
          <div style={{flex:1,background:C.card,border:"1px solid "+C.border,borderRadius:12,padding:"10px 14px",display:"flex",alignItems:"center",gap:8}}>
            <span style={{fontSize:18}}>🌙</span>
            <div>
              <div style={{fontSize:16,fontWeight:900,color:C.text}}>{(()=>{const sorted=[...workoutDates].sort();if(!sorted.length)return 0;const last=new Date(sorted[sorted.length-1]+"T12:00:00");return Math.max(0,Math.round((new Date()-last)/86400000)-1);})()}</div>
              <div style={{fontSize:9,color:C.sub}}>dias de descanso</div>
            </div>
          </div>
        </div>}
      </div>
      {/* Conteúdo scrollável */}
      <div style={{flex:1,overflowY:"auto"}}>
        {view==="mes"&&renderMes()}
        {view==="ano"&&renderAno()}
        {view==="plurianual"&&renderPlurianual()}
      </div>
    </div>
  );
}


function CorpoScreen({onNavigate,autoMeasure=false,savedCount=0}){
  const MEASURE_FIELDS=["Braço D","Braço E","Peito","Cintura","Coxa D","Panturrilha D"];
  const MUSCLE_GROUPS_ALL=["Peito","Costas","Pernas","Ombros","Braços","Core","Glúteos","Panturrilha"];
  const EX_MAP_VOL={"Peito":["Supino","Crucifixo","Peitoral","Inclinado","Declinado"],"Costas":["Terra","Remada","Puxada","Barra Fixa","Pull"],"Pernas":["Agachamento","Leg Press","Cadeira","Mesa Flexora","Afundo"],"Ombros":["Desenvolvimento","Elevação Lateral","Aberturas","Arnold","Ombro"],"Braços":["Rosca","Tríceps","Coice","Martelo","Scott","Concentrada","Extensão"],"Core":["Abdominal","Core","Prancha","Elevação De Pernas"],"Glúteos":["Agachamento","Afundo","Romeno","Leg Press","Hip Thrust","Glúteo"],"Panturrilha":["Panturrilha","Elevação de Panturrilha","Calf"]};

  // ── states (all hooks before any return) ──
  const[period,setPeriod]=useState("Semana");
  const[distPeriod,setDistPeriod]=useState("1m");
  const[weightGoal,setWeightGoal]=useState(loadWeightGoal);
  const[editingGoal,setEditingGoal]=useState(false);
  const[goalDraft,setGoalDraft]=useState("");
  const[measures,setMeasures]=useState(loadBodyMeasures);
  const[showAddMeasure,setShowAddMeasure]=useState(autoMeasure);
  const[showAddWeight,setShowAddWeight]=useState(false);
  const[weightDraft,setWeightDraft]=useState("");
  const[measureDraft,setMeasureDraft]=useState(autoMeasure?loadBodyMeasures():{});
  const[selMeasure,setSelMeasure]=useState("Braço D");
  const[measureHistory,setMeasureHistory]=useState(loadMeasureHistory);

  // ── muscle recovery (uses module-level RECOVERY_HRS / EX_TO_MUSCLE) ──
  const recoveryMuscles=useMemo(()=>{
    const nowMs=Date.now();
    const allSessions=getAllSessions();
    return Object.entries(RECOVERY_HRS).map(([g,hrs])=>{
      let lastMs=null;
      for(const s of allSessions){
        if(!s.date) continue;
        const trained=s.exercises?.some(e=>EX_TO_MUSCLE[g]?.some(kw=>(e.name||"").toLowerCase().includes(kw.toLowerCase())));
        if(trained){lastMs=new Date(s.date+"T12:00:00").getTime();break;}
      }
      if(!lastMs) return{g,pct:100,color:C.mint,lastDays:null};
      const elapsedHrs=(nowMs-lastMs)/3600000;
      const pct=Math.min(100,Math.round((elapsedHrs/hrs)*100));
      const color=pct>=100?C.mint:pct>=60?C.amber:C.coral;
      return{g,pct,color,lastDays:Math.round((nowMs-lastMs)/86400000)};
    });
  },[]);

  // ── volume per muscle for chosen period ──
  const periodDays={"Semana":7,"Mês":30,"Trim.":91,"Ano":365};
  const muscleVol=useMemo(()=>{
    const cutoff=new Date(Date.now()-(periodDays[period]||7)*86400000).toISOString().slice(0,10);
    const sessions=getAllSessions().filter(s=>s.date>=cutoff);
    return MUSCLE_GROUPS_ALL.reduce((acc,g)=>{
      const vol=sessions.reduce((sum,s)=>sum+(s.exercises||[]).filter(e=>EX_MAP_VOL[g]?.some(kw=>(e.name||"").toLowerCase().includes(kw.toLowerCase()))).reduce((a,e)=>a+(e.vol||0),0),0);
      const sets=sessions.reduce((sum,s)=>sum+(s.exercises||[]).filter(e=>EX_MAP_VOL[g]?.some(kw=>(e.name||"").toLowerCase().includes(kw.toLowerCase()))).reduce((a,e)=>a+(e.sets||0),0),0);
      acc[g]={vol:Math.round(vol/100)/10,sets};
      return acc;
    },{});
  },[period]);

  // ── volume spider (last 7 days, raw kg) ──
  const volumeByGroup=useMemo(()=>{
    const cutoff=new Date(Date.now()-7*86400000).toISOString().slice(0,10);
    const sessions=getAllSessions().filter(s=>s.date>=cutoff);
    const vol={};
    sessions.forEach(s=>{
      (s.exercises||[]).forEach(e=>{
        Object.entries(EX_MAP_VOL).forEach(([g,kws])=>{
          if(kws.some(kw=>(e.name||"").toLowerCase().includes(kw.toLowerCase()))){
            vol[g]=(vol[g]||0)+(e.vol||0);
          }
        });
      });
    });
    return vol;
  },[]);

  // ── body heat map ──
  const muscleHeat=useMemo(()=>{
    const now=Date.now();
    const heat={};
    recoveryMuscles.forEach(m=>{heat[m.g]=m.pct;});
    return heat;
  },[recoveryMuscles]);

  // ── weight ──
  const currentWeight=W_DATA[W_DATA.length-1];
  const startWeight=Math.max(...W_DATA);
  const weightPct=Math.max(0,Math.min(100,Math.round(((startWeight-currentWeight)/(startWeight-weightGoal))*100)));
  const weightChartData=W_DATA.map((y,i)=>({x:i,y}));

  const selMeasureChart=useMemo(()=>{
    return measureHistory.filter(h=>h[selMeasure]!=null).map((h,i)=>({x:i,y:parseFloat(h[selMeasure]||0)}));
  },[measureHistory,selMeasure]);

  const maxVol=Math.max(...Object.values(muscleVol).map(v=>v.vol),1);

  function saveGoal(){
    const v=parseFloat(goalDraft);
    if(!isNaN(v)&&v>0){setWeightGoal(v);saveWeightGoal(v);}
    setEditingGoal(false);
  }

  function saveMeasures(){
    const newM={...measures};
    MEASURE_FIELDS.forEach(f=>{if(measureDraft[f]) newM[f]=measureDraft[f];});
    setMeasures(newM);
    saveBodyMeasures(newM);
    if(MEASURE_FIELDS.some(f=>measureDraft[f])){
      const today=new Date().toISOString().slice(0,10);
      const newH=[...measureHistory,{date:today,...newM}];
      setMeasureHistory(newH);
      saveMeasureHistory(newH);
    }
    setShowAddMeasure(false);
    setMeasureDraft({});
  }

  const distPeriods=[{k:"1m",l:"Este mês",days:30},{k:"3m",l:"3 meses",days:90},{k:"1a",l:"Ano",days:365},{k:"all",l:"Tudo",days:9999}];
  const distCfg=distPeriods.find(p=>p.k===distPeriod)||distPeriods[0];
  const distCutoff=distCfg.days<9999?new Date(Date.now()-distCfg.days*86400000).toISOString().slice(0,10):"2000-01-01";
  const distPrevCutoff=distCfg.days<9999?new Date(Date.now()-distCfg.days*2*86400000).toISOString().slice(0,10):"2000-01-01";
  const allSForDist=getAllSessions();
  const distCurS=allSForDist.filter(s=>s.date>=distCutoff);
  const distPrevS=distCfg.days<9999?allSForDist.filter(s=>s.date>=distPrevCutoff&&s.date<distCutoff):[];
  const distStat=(ss)=>({count:ss.length,dur:ss.reduce((a,s)=>a+(s.duration||0),0),vol:ss.reduce((a,s)=>a+(s.totalVol||0),0),sets:ss.reduce((a,s)=>a+(s.totalSets||0),0)});
  const distCur=distStat(distCurS),distPrev=distStat(distPrevS);
  const distDiff=(a,b)=>b>0?Math.round((a-b)/b*100):null;
  const distVbg={};
  distCurS.forEach(s=>(s.exercises||[]).forEach(e=>{Object.entries(EX_MAP_VOL).forEach(([g,kws])=>{if(kws.some(kw=>(e.name||"").toLowerCase().includes(kw.toLowerCase())))distVbg[g]=(distVbg[g]||0)+(e.vol||0);});}));
  const distKpis=[{l:"Treinos",v:distCur.count,d:distDiff(distCur.count,distPrev.count)},{l:"Duração",v:distCur.dur>=60?Math.floor(distCur.dur/60)+"h"+(distCur.dur%60>0?" "+distCur.dur%60+"min":""):distCur.dur+"min",d:distDiff(distCur.dur,distPrev.dur)},{l:"Volume",v:distCur.vol.toFixed(1)+"t",d:distDiff(distCur.vol,distPrev.vol)},{l:"Séries",v:distCur.sets,d:distDiff(distCur.sets,distPrev.sets)}];

  return(
    <div className="screen-root" style={{background:"#080A0E",minHeight:"100vh",paddingBottom:120}}>

      {/* ── HEADER ── */}
      <div style={{position:"sticky",top:0,zIndex:9001,background:"rgba(5,6,9,0.98)",backdropFilter:"blur(24px)",padding:"8px 20px 14px"}}>
        <div style={{fontSize:26,fontWeight:900,color:C.text,letterSpacing:"-1px"}}>Meu Corpo</div>
      </div>

      <div style={{padding:"12px 16px 0"}}>

        {/* ── 1. PESO ── */}
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:16,marginBottom:12}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:10}}>
            <div>
              <div style={{fontSize:11,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:4}}>Peso Atual</div>
              <div style={{display:"flex",alignItems:"baseline",gap:5}}>
                <span style={{fontSize:40,fontWeight:900,color:C.text,letterSpacing:"-2px"}}>{currentWeight||"—"}</span>
                <span style={{fontSize:16,color:C.muted}}>kg</span>
              </div>
              {W_DATA.length>1&&<div style={{fontSize:12,fontWeight:700,color:(currentWeight-W_DATA[W_DATA.length-2])<=0?C.mint:C.coral,marginTop:2}}>
                {(currentWeight-W_DATA[W_DATA.length-2])>0?"+":""}{(currentWeight-(W_DATA[W_DATA.length-2]||currentWeight)).toFixed(1)}kg vs anterior
              </div>}
            </div>
            <div style={{display:"flex",flexDirection:"column",alignItems:"flex-end",gap:6}}>
              <button onClick={()=>{setWeightDraft("");setShowAddWeight(true);}} style={{background:C.blueXL,border:"none",borderRadius:10,padding:"8px 14px",color:"#fff",fontSize:12,fontWeight:700,cursor:"pointer"}}>+ Peso</button>
              <button onClick={()=>{setGoalDraft(String(weightGoal));setEditingGoal(true);}} style={{fontSize:11,color:C.muted,background:"none",border:"none",cursor:"pointer"}}>Meta: {weightGoal}kg ✎</button>
            </div>
          </div>
          <LineChart data={weightChartData} color={C.mint} height={72}/>
          <div style={{marginTop:10}}>
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:4}}>
              <span style={{fontSize:10,color:C.muted}}>Início {startWeight}kg</span>
              <span style={{fontSize:10,color:C.mint,fontWeight:700}}>{weightPct}% do objetivo · Meta {weightGoal}kg</span>
            </div>
            <div style={{background:C.surface,borderRadius:6,height:6,overflow:"hidden"}}>
              <div style={{width:weightPct+"%",height:"100%",background:"linear-gradient(90deg,"+C.blueXL+","+C.mint+")",borderRadius:6,transition:"width 0.6s"}}/>
            </div>
          </div>
        </div>

        {/* ── 2. RECUPERAÇÃO ── */}
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:16,marginBottom:12}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
            <div style={{fontSize:12,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.08em"}}>Recuperação Muscular</div>
            <div style={{display:"flex",gap:8}}>
              {[{v:recoveryMuscles.filter(m=>m.pct>=100).length,l:"Prontos",c:C.mint},
                {v:recoveryMuscles.filter(m=>m.pct>=60&&m.pct<100).length,l:"Rec.",c:C.amber},
                {v:recoveryMuscles.filter(m=>m.pct<60).length,l:"Fatig.",c:C.coral}
              ].map(s=>(
                <div key={s.l} style={{textAlign:"center"}}>
                  <div style={{fontSize:16,fontWeight:900,color:s.c}}>{s.v}</div>
                  <div style={{fontSize:8,color:C.muted}}>{s.l}</div>
                </div>
              ))}
            </div>
          </div>
          {recoveryMuscles.map(m=>(
            <div key={m.g} style={{display:"flex",alignItems:"center",gap:10,marginBottom:8}}>
              <div style={{fontSize:11,fontWeight:600,color:C.sub,width:70,flexShrink:0}}>{m.g}</div>
              <div style={{flex:1,height:7,background:C.surface,borderRadius:4,overflow:"hidden"}}>
                <div style={{height:"100%",width:m.pct+"%",background:m.color,borderRadius:4,transition:"width 0.5s"}}/>
              </div>
              <div style={{fontSize:11,fontWeight:700,color:m.color,width:30,textAlign:"right"}}>{m.pct>=100?"✓":m.pct+"%"}</div>
              {m.lastDays!=null&&<div style={{fontSize:9,color:C.muted,width:28,textAlign:"right"}}>há {m.lastDays}d</div>}
            </div>
          ))}
          <div style={{marginTop:8,fontSize:9,color:C.muted,paddingTop:8,borderTop:"1px solid "+C.border}}>Core 36h · Ombros/Braços 48h · Peito 60h · Costas 72h · Pernas 96h</div>
        </div>

        {/* ── 3. DISTRIBUIÇÃO MUSCULAR ── */}
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:16,marginBottom:12}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
            <div style={{fontSize:12,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.08em"}}>Distribuição Muscular</div>
            <div style={{display:"flex",gap:4}}>
              {distPeriods.map(p=>(
                <button key={p.k} onClick={()=>setDistPeriod(p.k)} style={{padding:"3px 8px",borderRadius:99,fontSize:9,fontWeight:700,cursor:"pointer",background:distPeriod===p.k?C.blueXL:"transparent",border:"1px solid "+(distPeriod===p.k?C.blueXL:C.border),color:distPeriod===p.k?"#fff":C.sub}}>{p.l}</button>
              ))}
            </div>
          </div>
          <VolumeSpiderChart volumeByGroup={distVbg} size={Math.min(240,window.innerWidth-80)}/>
        </div>

        {/* ── 4. VOLUME POR GRUPO ── */}
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:16,marginBottom:12}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12}}>
            <div style={{fontSize:12,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.08em"}}>Volume por Grupo</div>
            <div style={{display:"flex",background:C.surface,borderRadius:8,padding:2,border:"1px solid "+C.border}}>
              {["Semana","Mês","Trim.","Ano"].map(p=>(
                <button key={p} onClick={()=>setPeriod(p)} style={{padding:"3px 8px",borderRadius:6,border:"none",cursor:"pointer",fontSize:10,fontWeight:700,background:period===p?"rgba(255,255,255,0.12)":"transparent",color:period===p?C.text:C.muted}}>{p}</button>
              ))}
            </div>
          </div>
          {MUSCLE_GROUPS_ALL.map(g=>{
            const mv=muscleVol[g]||{vol:0,sets:0};
            const barPct=maxVol>0?mv.vol/maxVol:0;
            const setsOk=mv.sets>=6&&mv.sets<=20;
            const setsColor=mv.sets===0?C.muted:setsOk?C.mint:mv.sets>20?C.coral:C.amber;
            return(
              <div key={g} style={{marginBottom:10}}>
                <div style={{display:"flex",justifyContent:"space-between",marginBottom:4}}>
                  <span style={{fontSize:12,fontWeight:700,color:GC[g]||C.blueXL}}>{g}</span>
                  <div style={{display:"flex",gap:10,alignItems:"center"}}>
                    <span style={{fontSize:10,fontWeight:700,color:setsColor}}>{mv.sets>0?mv.sets+" séries"+(setsOk?" ✓":""):"—"}</span>
                    <span style={{fontSize:12,fontWeight:700,color:C.text}}>{mv.vol>0?mv.vol+"t":"—"}</span>
                  </div>
                </div>
                <div style={{height:6,background:C.surface,borderRadius:3,overflow:"hidden"}}>
                  <div style={{height:"100%",width:(barPct*100)+"%",background:GC[g]||C.blueXL,borderRadius:3,transition:"width 0.5s",opacity:0.8}}/>
                </div>
              </div>
            );
          })}
          <div style={{display:"flex",gap:12,marginTop:10,paddingTop:10,borderTop:"1px solid "+C.border}}>
            {[{c:C.mint,l:"6–20 ideal"},{c:C.amber,l:"<6 abaixo"},{c:C.coral,l:">20 excesso"}].map(i=>(
              <div key={i.l} style={{display:"flex",alignItems:"center",gap:4}}><div style={{width:6,height:6,borderRadius:"50%",background:i.c}}/><span style={{fontSize:9,color:C.muted}}>{i.l}</span></div>
            ))}
          </div>
        </div>

        {/* ── 4. MAPA MUSCULAR ── */}
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:16,marginBottom:12}}>
          <div style={{fontSize:12,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:12}}>Mapa Muscular</div>
          <BodyDiagram muscleHeat={muscleHeat} width={Math.min(300,window.innerWidth-64)} savedCount={savedCount}/>
          <div style={{display:"flex",justifyContent:"center",gap:12,marginTop:8,flexWrap:"wrap"}}>
            {[{c:"#3B82F6",o:1,l:"Fatigado"},{c:"#3B82F6",o:0.55,l:"Recuperando"},{c:"#3B82F6",o:0.25,l:"Quase pronto"},{c:C.muted,o:1,l:"Descansado"}].map(item=>(
              <div key={item.l} style={{display:"flex",alignItems:"center",gap:4}}>
                <div style={{width:7,height:7,borderRadius:"50%",background:item.c,opacity:item.o}}/>
                <span style={{fontSize:9,color:C.muted}}>{item.l}</span>
              </div>
            ))}
          </div>
        </div>

        {/* ── 5. MEDIDAS ── */}
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:16,marginBottom:12}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12}}>
            <div style={{fontSize:12,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.08em"}}>Medidas Corporais</div>
            <button onClick={()=>{setMeasureDraft(measures);setShowAddMeasure(true);}} style={{background:C.blueXL,border:"none",borderRadius:10,padding:"7px 14px",color:"#fff",fontSize:12,fontWeight:700,cursor:"pointer"}}>Atualizar</button>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10,marginBottom:14}}>
            {MEASURE_FIELDS.map(f=>(
              <div key={f} style={{background:C.surface,borderRadius:12,padding:"10px 10px"}}>
                <div style={{fontSize:9,fontWeight:700,color:C.muted,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:4}}>{f}</div>
                <div style={{fontSize:18,fontWeight:900,color:measures[f]?C.text:C.muted}}>{measures[f]||"—"}<span style={{fontSize:10,color:C.muted,marginLeft:2}}>{measures[f]?"cm":""}</span></div>
              </div>
            ))}
          </div>
        </div>

      </div>

      {/* ── MODALS ── */}
      {showAddWeight&&(
        <div style={{position:"fixed",inset:0,zIndex:900,background:"rgba(0,0,0,0.75)",backdropFilter:"blur(8px)",display:"flex",alignItems:"flex-end"}}>
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:"20px 20px 0 0",padding:"24px 20px calc(40px + env(safe-area-inset-bottom,0px))",width:"100%"}}>
            <div style={{fontSize:16,fontWeight:800,color:C.text,marginBottom:16}}>Atualizar Peso</div>
            <input type="number" step="0.1" placeholder="Ex: 78.5" value={weightDraft} onChange={e=>setWeightDraft(e.target.value)} style={{width:"100%",boxSizing:"border-box",background:C.surface,border:"1px solid "+C.border,borderRadius:12,padding:"14px 16px",fontSize:24,fontWeight:900,color:C.text,outline:"none",textAlign:"center",marginBottom:16}} autoFocus/>
            <div style={{display:"flex",gap:10}}>
              <button onClick={()=>setShowAddWeight(false)} style={{flex:1,padding:"13px",borderRadius:12,background:C.surface,border:"1px solid "+C.border,color:C.sub,fontWeight:700,cursor:"pointer"}}>Cancelar</button>
              <button onClick={async()=>{const v=parseFloat(weightDraft);if(!isNaN(v)&&v>0){await saveWeight(v);refreshDerivedData();setShowAddWeight(false);}}} style={{flex:1,padding:"13px",borderRadius:12,background:C.blueXL,border:"none",color:"#fff",fontWeight:800,cursor:"pointer"}}>Salvar</button>
            </div>
          </div>
        </div>
      )}
      {editingGoal&&(
        <div style={{position:"fixed",inset:0,zIndex:900,background:"rgba(0,0,0,0.75)",backdropFilter:"blur(8px)",display:"flex",alignItems:"flex-end"}}>
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:"20px 20px 0 0",padding:"24px 20px calc(40px + env(safe-area-inset-bottom,0px))",width:"100%"}}>
            <div style={{fontSize:16,fontWeight:800,color:C.text,marginBottom:16}}>Meta de Peso</div>
            <input type="number" step="0.1" placeholder="Ex: 74" value={goalDraft} onChange={e=>setGoalDraft(e.target.value)} style={{width:"100%",boxSizing:"border-box",background:C.surface,border:"1px solid "+C.border,borderRadius:12,padding:"14px 16px",fontSize:24,fontWeight:900,color:C.text,outline:"none",textAlign:"center",marginBottom:16}} autoFocus/>
            <div style={{display:"flex",gap:10}}>
              <button onClick={()=>setEditingGoal(false)} style={{flex:1,padding:"13px",borderRadius:12,background:C.surface,border:"1px solid "+C.border,color:C.sub,fontWeight:700,cursor:"pointer"}}>Cancelar</button>
              <button onClick={saveGoal} style={{flex:1,padding:"13px",borderRadius:12,background:C.blueXL,border:"none",color:"#fff",fontWeight:800,cursor:"pointer"}}>Salvar</button>
            </div>
          </div>
        </div>
      )}
      {showAddMeasure&&(
        <div style={{position:"fixed",inset:0,zIndex:900,background:"rgba(0,0,0,0.75)",backdropFilter:"blur(8px)",display:"flex",alignItems:"flex-end"}}>
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:"20px 20px 0 0",padding:"24px 20px calc(40px + env(safe-area-inset-bottom,0px))",width:"100%"}}>
            <div style={{fontSize:16,fontWeight:800,color:C.text,marginBottom:4}}>Atualizar Medidas</div>
            <div style={{fontSize:11,color:C.muted,marginBottom:14}}>Deixe em branco para não alterar</div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:16}}>
              {MEASURE_FIELDS.map(f=>(
                <div key={f}>
                  <div style={{fontSize:10,color:C.muted,fontWeight:600,marginBottom:4}}>{f.toUpperCase()} (cm)</div>
                  <input value={measureDraft[f]||""} onChange={e=>setMeasureDraft(d=>({...d,[f]:e.target.value}))} type="number" step="0.1" placeholder="—" style={{width:"100%",boxSizing:"border-box",background:C.surface,border:"1px solid "+C.border,borderRadius:10,padding:"10px 12px",fontSize:16,fontWeight:700,color:C.text,outline:"none"}}/>
                </div>
              ))}
            </div>
            <div style={{display:"flex",gap:10}}>
              <button onClick={()=>setShowAddMeasure(false)} style={{flex:1,padding:"13px",borderRadius:12,background:C.surface,border:"1px solid "+C.border,color:C.sub,fontWeight:700,cursor:"pointer"}}>Cancelar</button>
              <button onClick={saveMeasures} style={{flex:1,padding:"13px",borderRadius:12,background:C.blueXL,border:"none",color:"#fff",fontWeight:800,cursor:"pointer"}}>Salvar</button>
            </div>
          </div>
        </div>
      )}

      <BottomNav active="corpo" onNavigate={onNavigate}/>
    </div>
  );
}

function CoachScreen({onNavigate}){
  const[messages,setMessages]=useState([{role:"assistant",content:"Olá! Sou o Coach Carbon, seu personal trainer com IA. Posso analisar seus treinos, sugerir exercícios e te ajudar a atingir seus objetivos. Como posso te ajudar hoje?"}]);
  const[input,setInput]=useState("");
  const[loading,setLoading]=useState(false);
  const scrollRef=useRef(null);

  useEffect(()=>{
    if(scrollRef.current) scrollRef.current.scrollTop=scrollRef.current.scrollHeight;
  },[messages,loading]);

  function buildSystemPrompt(){
    const sessions=getAllSessions().slice(0,10);
    const w=W_DATA[W_DATA.length-1];
    const weightTrend=W_DATA.length>1?`${W_DATA[0]}kg → ${w}kg (${(w-W_DATA[0]).toFixed(1)}kg total)`:w+"kg";

    // Histórico detalhado com exercícios, séries, cargas e progressão
    const ctx=sessions.length>0
      ?sessions.map(s=>{
          const exStr=(s.exercises||[]).map(e=>{
            const sets=(e.setData||[]).map(st=>`${st.w||0}kg×${st.r}`).join(", ");
            return `  - ${e.name}: ${sets}${e.setData?.[0]?.rpe?" @"+e.setData[0].rpe+" RPE":""}`;
          }).join("\n");
          return `📅 ${s.date} — ${s.name} (${Math.round(s.duration||0)}min, ${s.totalVol||0}t)\n${exStr}`;
        }).join("\n\n")
      :"Nenhum treino registrado ainda.";

    // Progressão de carga por exercício (últimas 3 sessões de cada)
    const progressão=Object.entries(HIST).slice(0,8).map(([ex,hist])=>{
      const last3=hist.slice(0,3).map(h=>{
        const best=(h.sets||[]).reduce((a,s)=>s.w>a?s.w:a,0);
        return `${h.d}: ${best}kg`;
      }).join(" → ");
      return `  ${ex}: ${last3}`;
    }).join("\n");

    const measureStr=_measureHistoryCache.length>0
      ?`Peso atual: ${w}kg | Tendência: ${weightTrend}\nÚltimas medidas: ${JSON.stringify(_measureHistoryCache[_measureHistoryCache.length-1])}`
      :`Peso atual: ${w||"—"}kg`;

    return `Você é o Coach Carbon, personal trainer e nutricionista virtual especializado em musculação e emagrecimento. Você TEM ACESSO COMPLETO aos dados do atleta abaixo.

**📊 DADOS DO ATLETA:**
${measureStr}

**🏋️ HISTÓRICO DETALHADO (últimos 10 treinos):**
${ctx}

**📈 PROGRESSÃO DE CARGA POR EXERCÍCIO:**
${progressão}

**Instruções:**
- Responda SEMPRE em português brasileiro
- Use os dados reais do atleta nas análises — você TEM esses dados
- Seja direto, preciso e motivador
- Máximo 3 parágrafos, use dados concretos quando relevante`;
  }

  async function send(){
    const text=input.trim();
    if(!text||loading) return;
    const newMsgs=[...messages,{role:"user",content:text}];
    setMessages(newMsgs);
    setInput("");
    setLoading(true);
    try{
      const{data,error}=await supabase.functions.invoke("anthropic-proxy",{
        body:{model:"claude-sonnet-4-6",max_tokens:1000,system:buildSystemPrompt(),messages:newMsgs.map(m=>({role:m.role,content:m.content}))}
      });
      if(error) throw error;
      const txt=data?.content?.find(b=>b.type==="text")?.text;
      if(!txt) throw new Error("Sem resposta");
      setMessages(m=>[...m,{role:"assistant",content:txt}]);
    }catch(e){
      setMessages(m=>[...m,{role:"assistant",content:"❌ Erro: "+e.message}]);
    }finally{setLoading(false);}
  }

  const chips=["Qual músculo treinar hoje?","Dicas para cortar gordura","Monte um treino de costas","Como melhorar meu Supino?","Analise minha semana"];
  const showChips=messages.length===1&&!loading;

  return(
    <div style={{display:"flex",flexDirection:"column",height:"100%",background:"#080A0E"}}>
      <style>{`@keyframes fgpulse{0%,100%{opacity:0.3;transform:scale(0.75)}50%{opacity:1;transform:scale(1)}}`}</style>

      {/* Title */}
      <div style={{flexShrink:0,padding:"8px 20px 12px"}}>
        <div style={{fontSize:26,fontWeight:900,color:"#FFFFFF",letterSpacing:"-1px"}}>AI Coach</div>
        <div style={{fontSize:10,fontWeight:600,color:C.blueXL,letterSpacing:"0.1em",textTransform:"uppercase",marginTop:3}}>Powered by Claude</div>
      </div>

      {/* Messages — scrollable, padded so content clears fixed input+nav */}
      <div ref={scrollRef} style={{flex:1,overflowY:"auto",padding:"0 16px",display:"flex",flexDirection:"column",gap:12,paddingBottom:220}}>
        {messages.map((m,i)=>(
          <div key={i} style={{display:"flex",justifyContent:m.role==="user"?"flex-end":"flex-start",alignItems:"flex-end",gap:8}}>
            {m.role==="assistant"&&<div style={{width:28,height:28,borderRadius:"50%",background:"#080A0E",border:"1px solid rgba(255,255,255,0.1)",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,overflow:"hidden"}}><img src="/carbon-logo-transparent.png" alt="Carbon" style={{width:20,height:20,objectFit:"contain"}}/></div>}
            <div style={{maxWidth:"78%",background:m.role==="user"?"linear-gradient(135deg,#2563EB,#1D4ED8)":"rgba(255,255,255,0.06)",border:m.role==="user"?"none":"1px solid rgba(255,255,255,0.08)",borderRadius:m.role==="user"?"18px 18px 4px 18px":"18px 18px 18px 4px",padding:"10px 14px",fontSize:13,lineHeight:1.6,color:m.role==="user"?"#fff":C.text,wordBreak:"break-word"}}>
              {m.role==="user"?m.content:m.content.split("\n").map((line,li)=>{
                const parseLine=(txt)=>{const parts=[];let rest=txt;let key=0;while(rest.length>0){const bold=rest.match(/^\*\*(.+?)\*\*/);const italic=rest.match(/^\*(.+?)\*/);if(bold){parts.push(<strong key={key++} style={{fontWeight:800,color:"#fff"}}>{bold[1]}</strong>);rest=rest.slice(bold[0].length);}else if(italic){parts.push(<em key={key++} style={{fontStyle:"italic"}}>{italic[1]}</em>);rest=rest.slice(italic[0].length);}else{const next=rest.search(/\*\*/);const ni=rest.search(/\*[^*]/);const stop=next===-1&&ni===-1?rest.length:Math.min(next===-1?Infinity:next,ni===-1?Infinity:ni);parts.push(<span key={key++}>{rest.slice(0,stop)}</span>);rest=rest.slice(stop);}}return parts;};
                if(line.trim()==="")return <div key={li} style={{height:6}}/>;
                if(line.startsWith("- ")||line.startsWith("• "))return <div key={li} style={{display:"flex",gap:6,marginBottom:2}}><span style={{flexShrink:0,marginTop:2}}>•</span><span>{parseLine(line.replace(/^[-•]\s/,""))}</span></div>;
                return <div key={li} style={{marginBottom:2}}>{parseLine(line)}</div>;
              })}
            </div>
          </div>
        ))}
        {loading&&<div style={{display:"flex",alignItems:"flex-end",gap:8}}><div style={{width:28,height:28,borderRadius:"50%",background:"#080A0E",border:"1px solid rgba(255,255,255,0.1)",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,overflow:"hidden"}}><img src="/carbon-logo-transparent.png" alt="Carbon" style={{width:20,height:20,objectFit:"contain"}}/></div><div style={{background:"rgba(255,255,255,0.06)",border:"1px solid "+C.border,borderRadius:"18px 18px 18px 4px",padding:"12px 16px",display:"flex",gap:5,alignItems:"center"}}>{[0,1,2].map(j=>(<div key={j} style={{width:7,height:7,borderRadius:"50%",background:C.blueXL,animationName:"fgpulse",animationDuration:"1.2s",animationTimingFunction:"ease-in-out",animationIterationCount:"infinite",animationDelay:`${j*0.18}s`}}/>))}</div></div>}
      </div>

      {/* Fixed bottom: input ABOVE nav bar */}
      <div style={{position:"fixed",bottom:0,left:0,right:0,zIndex:200}}>
        {/* Nav bar */}
        <BottomNav active="coach" onNavigate={onNavigate}/>
      </div>

      {/* Input bar - sits above the nav bar */}
      <div style={{position:"fixed",bottom:"calc(88px + env(safe-area-inset-bottom,0px))",left:0,right:0,zIndex:201,background:"rgba(8,10,14,0.97)",backdropFilter:"blur(24px)",borderTop:"1px solid rgba(255,255,255,0.08)",padding:"10px 12px"}}>
        {showChips&&<div style={{display:"flex",gap:8,overflowX:"auto",marginBottom:10,paddingBottom:2}}>{chips.map(c=>(<button key={c} onClick={()=>setInput(c)} style={{flexShrink:0,background:"rgba(59,130,246,0.1)",border:"1px solid rgba(59,130,246,0.22)",borderRadius:20,padding:"7px 13px",fontSize:11,fontWeight:600,color:C.blueXL,cursor:"pointer",whiteSpace:"nowrap"}}>{c}</button>))}</div>}
        <div style={{display:"flex",gap:10,alignItems:"flex-end"}}>
          <textarea value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();send();}}} placeholder="Pergunte ao seu coach..." rows={1} style={{flex:1,background:"rgba(255,255,255,0.07)",border:"1px solid rgba(255,255,255,0.12)",borderRadius:22,padding:"12px 16px",fontSize:15,color:C.text,outline:"none",resize:"none",fontFamily:"inherit",lineHeight:1.45,maxHeight:120,overflowY:"auto"}}/>
          <button onClick={send} disabled={!input.trim()||loading} style={{width:44,height:44,borderRadius:"50%",background:input.trim()&&!loading?"linear-gradient(135deg,#3B82F6,#2563EB)":"rgba(255,255,255,0.08)",border:"none",cursor:input.trim()&&!loading?"pointer":"default",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,opacity:input.trim()&&!loading?1:0.4}}>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none"><path d="M12 19V5M5 12l7-7 7 7" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
          </button>
        </div>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
// GLOBAL WORKOUT BAR — persists across all screens
// ══════════════════════════════════════════════════════════════
function GlobalWorkoutBar({workout,onOpen,onEnd}){
  const{plan,exercises,elapsed,currentEx}=workout;
  const[showConfirm,setShowConfirm]=useState(false);
  const totalDone=exercises.reduce((n,e)=>n+e.activeSets.filter(s=>s.done&&s.type==="work").length,0);
  const totalSets=exercises.reduce((n,e)=>n+e.activeSets.filter(s=>s.type==="work").length,0);
  return(
    <>
      <div style={{position:"fixed",bottom:"calc(88px + env(safe-area-inset-bottom, 0px))",left:12,right:12,zIndex:150,background:C.surface+"F8",backdropFilter:"blur(20px)",borderRadius:18,border:"1px solid "+C.mint+"44",boxShadow:"0 4px 32px rgba(0,0,0,0.5)",overflow:"hidden"}}>
        <div style={{display:"flex",alignItems:"center",gap:10,padding:"12px 16px",cursor:"pointer"}} onClick={onOpen}>
          <button onClick={e=>{e.stopPropagation();onOpen();}} style={{width:32,height:32,borderRadius:99,background:C.surface,border:"1px solid "+C.border,color:C.sub,fontSize:16,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>⌃</button>
          <div style={{width:8,height:8,borderRadius:"50%",background:C.mint,flexShrink:0}}/>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontSize:13,fontWeight:700,color:C.text}}>{plan?.name} · {plan?.label} <span style={{color:C.sub,fontWeight:400}}>· {fmt(elapsed)}</span></div>
            <div style={{fontSize:11,color:C.sub,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{exercises[currentEx]?.name||""}</div>
          </div>
          <div style={{fontSize:12,fontWeight:700,color:C.blueXL,flexShrink:0}}>{totalDone}/{totalSets}</div>
          <button onClick={e=>{e.stopPropagation();setShowConfirm(true);}} style={{width:36,height:36,background:"none",border:"none",borderRadius:10,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none"><path d="M3 6h18M8 6V4h8v2M19 6l-1 14H6L5 6" stroke="#EF4444" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/><path d="M10 11v5M14 11v5" stroke="#EF4444" strokeWidth="1.8" strokeLinecap="round"/></svg>
          </button>
        </div>
      </div>
      {showConfirm&&<div style={{position:"fixed",inset:0,zIndex:600,background:"#000000CC",display:"flex",alignItems:"center",justifyContent:"center",padding:24}}>
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:24,padding:28,width:"100%",maxWidth:320,textAlign:"center"}}>
          <div style={{fontSize:22,fontWeight:800,color:C.text,marginBottom:8}}>Encerrar treino?</div>
          <div style={{fontSize:14,color:C.sub,marginBottom:24}}>O progresso atual será salvo.</div>
          <div style={{display:"flex",gap:10}}>
            <button onClick={()=>setShowConfirm(false)} style={{flex:1,padding:"14px",background:C.surface,border:"1px solid "+C.border,borderRadius:14,color:C.sub,fontSize:14,fontWeight:600,cursor:"pointer"}}>Cancelar</button>
            <button onClick={()=>{setShowConfirm(false);onEnd();}} style={{flex:1,padding:"14px",background:C.coral,border:"none",borderRadius:14,color:"#fff",fontSize:14,fontWeight:700,cursor:"pointer"}}>Encerrar</button>
          </div>
        </div>
      </div>}
    </>
  );
}

// ══════════════════════════════════════════════════════════════
// ROOT APP
// ══════════════════════════════════════════════════════════════
function ForgeAppInner(){
  const[screen,setScreen]=useState("home");
  const[exName,setExName]=useState(null);
  const[savedCount,setSavedCount]=useState(0);

  // Scroll to top em toda troca de tela
  useEffect(()=>{
    window.scrollTo(0,0);
    document.documentElement.scrollTop=0;
    document.body.scrollTop=0;
    // Reseta todos os containers scrolláveis da app
    setTimeout(()=>{
      document.querySelectorAll(".screen-root").forEach(el=>{el.scrollTop=0;});
    },0);
  },[screen]);

  // ── Global workout state lifted here ──
  const[activeWorkout,setActiveWorkout]=useState(null); // null = no active workout
  // activeWorkout: { plan, exercises, currentEx, elapsed, startTs }
  const elapsedRef=useRef(0);
  const timerRef=useRef(null);

  // Global elapsed ticker — runs regardless of which screen is shown
  useEffect(()=>{
    if(activeWorkout){
      timerRef.current=setInterval(()=>{
        setActiveWorkout(prev=>prev?{...prev,elapsed:Math.floor((Date.now()-prev.startTs)/1000)}:null);
      },1000);
    } else {
      clearInterval(timerRef.current);
    }
    return()=>clearInterval(timerRef.current);
  },[!!activeWorkout]);

  function startWorkout(plan,exercises){
    const startTs=Date.now();
    setActiveWorkout({plan,exercises,currentEx:0,elapsed:0,startTs});
    setTreinoSub("active");
    setScreen("treino");
    // Incrementa cacheVersion para forçar re-render do ExerciseHistory com dados frescos
    setSavedCount(c=>c+1);
  }

  function endWorkout(){
    setActiveWorkout(null);
    setScreen("treino");
  }

  function updateWorkout(patch){
    setActiveWorkout(prev=>prev?{...prev,...(typeof patch==="function"?patch(prev):patch)}:prev);
  }

  function navigate(dest,params){
    if(dest==="exercicio"&&params?.name) setExName(params.name);
    window.scrollTo(0,0);
    document.documentElement.scrollTop=0;
    document.body.scrollTop=0;
    setScreen(dest);
  }

  const activeNav=["home","treino","progresso","corpo","coach"].includes(screen)?screen:
    screen==="historico"||screen==="calendario"||screen==="progresso_det"?"progresso":
    screen==="exercicio"||screen==="exercicios_browser"?"treino":
    screen==="medicoes"||screen==="corpo"?"corpo":"home";

  const[treinoSub,setTreinoSub]=useState("plans");
  const[forceActive,setForceActive]=useState(0);
  const prevScreenRef=useRef("treino");

  const showMiniBar=!!activeWorkout&&!(screen==="treino"&&treinoSub==="active");

  function openActiveWorkout(){
    prevScreenRef.current=screen;
    setScreen("treino");
    setForceActive(n=>n+1);
    setTreinoSub("active");
  }

  return(
    <div>
      <GlobalHeader/>
      {screen==="home"&&<HomeScreen onNavigate={navigate} onStartWorkout={startWorkout} onSessionDeleted={()=>setSavedCount(c=>c+1)} savedCount={savedCount}/>}
      {screen==="treino"&&<TreinoScreen onNavigate={navigate} activeWorkout={activeWorkout} onStartWorkout={startWorkout} onEndWorkout={endWorkout} onUpdateWorkout={updateWorkout} onSubScreen={setTreinoSub} forceActive={forceActive} onMinimize={()=>navigate(prevScreenRef.current)} onWorkoutSaved={()=>setSavedCount(c=>c+1)} cacheVersion={savedCount}/>}
      {screen==="exercicio"&&<ExercicioScreen name={exName} onNavigate={navigate}/>}
      {screen==="exercicios_browser"&&<ExerciciosBrowserScreen onNavigate={navigate}/>}
      {screen==="historico"&&<HistoricoScreen onNavigate={navigate}/>}
      {screen==="calendario"&&<CalendarioFullScreen onNavigate={navigate}/>}
      {screen==="progresso"&&<ProgressoScreen onNavigate={navigate} savedCount={savedCount}/>}
      {screen==="corpo"&&<CorpoScreen onNavigate={navigate} savedCount={savedCount}/>}
      {screen==="medicoes"&&<MedicoesScreen onNavigate={navigate}/>}
      {screen==="coach"&&<CoachScreen onNavigate={navigate}/>}
      {!["home","treino","exercicio","exercicios_browser","historico","calendario","progresso","corpo","medicoes","coach"].includes(screen)&&<HomeScreen onNavigate={navigate} onStartWorkout={startWorkout} onSessionDeleted={()=>setSavedCount(c=>c+1)} savedCount={savedCount}/>}
      {showMiniBar&&<GlobalWorkoutBar workout={activeWorkout} onOpen={openActiveWorkout} onEnd={endWorkout}/>}
    </div>
  );
}

// ─── LOGIN ───────────────────────────────────────────────────
function LoginScreen(){
  const[email,setEmail]=useState("");
  const[password,setPassword]=useState("");
  const[err,setErr]=useState(null);
  const[loading,setLoading]=useState(false);

  async function handleLogin(e){
    e.preventDefault();
    setErr(null);setLoading(true);
    const{error}=await supabase.auth.signInWithPassword({email,password});
    if(error)setErr("Email ou senha incorretos.");
    setLoading(false);
  }

  return(
    <div style={{
      position:"fixed",inset:0,
      background:"#000000",
      display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",
      padding:"0 40px",
    }}>
      <div style={{width:"100%",maxWidth:340,display:"flex",flexDirection:"column",alignItems:"center"}}>
        {/* Logo */}
        <div style={{marginBottom:48,display:"flex",flexDirection:"column",alignItems:"center"}}>
          <img src="/carbon-logo-transparent.png" alt="Carbon" style={{width:160,objectFit:"contain"}}/>
        </div>

        {/* Form */}
        <form onSubmit={handleLogin} style={{width:"100%"}}>
          <input
            type="email" autoCapitalize="none" autoCorrect="off"
            placeholder="Email"
            value={email} onChange={e=>setEmail(e.target.value)} required
            style={{
              width:"100%",boxSizing:"border-box",
              background:"transparent",
              border:"none",borderBottom:"1px solid rgba(255,255,255,0.2)",
              borderRadius:0,padding:"14px 0",
              fontSize:15,color:"#fff",outline:"none",marginBottom:20,
              letterSpacing:"0.02em",
            }}
          />
          <input
            type="password" placeholder="Senha"
            value={password} onChange={e=>setPassword(e.target.value)} required
            style={{
              width:"100%",boxSizing:"border-box",
              background:"transparent",
              border:"none",borderBottom:"1px solid rgba(255,255,255,0.2)",
              borderRadius:0,padding:"14px 0",
              fontSize:15,color:"#fff",outline:"none",marginBottom:36,
              letterSpacing:"0.1em",
            }}
          />
          {err&&<div style={{color:"#EF4444",fontSize:12,marginBottom:16,textAlign:"center",letterSpacing:"0.05em"}}>{err}</div>}
          <button type="submit" disabled={loading} style={{
            width:"100%",padding:"16px",
            background:"transparent",
            border:"1px solid rgba(255,255,255,0.25)",
            borderRadius:2,color:"#fff",
            fontSize:11,fontWeight:500,cursor:"pointer",
            opacity:loading?0.5:1,
            letterSpacing:"0.3em",textTransform:"uppercase",
          }}>{loading?"ENTRANDO...":"ENTRAR"}</button>
        </form>

        <div style={{marginTop:60,fontSize:9,color:"rgba(255,255,255,0.15)",letterSpacing:"0.3em",textTransform:"uppercase"}}>Train · Recover · Evolve</div>
      </div>
    </div>
  );
}

// ─── CARBON INTRO SCREEN ─────────────────────────────────────
function CarbonIntro({onDone}){
  const[visible,setVisible]=useState(false);
  const[fading,setFading]=useState(false);

  useEffect(()=>{
    document.body.classList.add("hide-carbon-header");
    const t1=setTimeout(()=>setVisible(true),150);
    const t2=setTimeout(()=>setFading(true),2600);
    const t3=setTimeout(()=>{document.body.classList.remove("hide-carbon-header");onDone();},3200);
    return()=>{clearTimeout(t1);clearTimeout(t2);clearTimeout(t3);document.body.classList.remove("hide-carbon-header");};
  },[]);

  return(
    <div
      onClick={()=>{setFading(true);document.body.classList.remove("hide-carbon-header");setTimeout(onDone,500);}}
      style={{
        position:"fixed",inset:0,zIndex:9999,
        background:"#000000",
        display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",
        cursor:"pointer",
        opacity:fading?0:visible?1:0,
        transition:fading?"opacity 0.5s ease":"opacity 1s ease",
      }}>
      <div style={{
        display:"flex",flexDirection:"row",alignItems:"center",gap:16,
        transform:visible?"translateY(0)":"translateY(16px)",
        transition:"transform 1.2s ease",
      }}>
        <img src="/carbon-logo-transparent.png" alt="Carbon" style={{height:60,objectFit:"contain"}}/>
        <div style={{fontSize:28,fontWeight:300,color:"#fff",letterSpacing:"0.4em",textTransform:"uppercase"}}>CARBON</div>
      </div>
    </div>
  );
}

function SplashLoading(){
  return(
    <div style={{position:"fixed",inset:0,background:"#000000",display:"flex",alignItems:"center",justifyContent:"center",gap:16}}>
      <img src="/carbon-logo-transparent.png" alt="Carbon" style={{height:60,objectFit:"contain"}}/>
      <div style={{fontSize:28,fontWeight:300,color:"#fff",letterSpacing:"0.4em",textTransform:"uppercase"}}>CARBON</div>
    </div>
  );
}

// ─── ROOT: AUTH + DATA GATE ──────────────────────────────────
export default function ForgeApp(){
  const[session,setSession]=useState(undefined);
  const[dataReady,setDataReady]=useState(false);
  const[introDone,setIntroDone]=useState(false);

  useEffect(()=>{
    supabase.auth.getSession().then(({data})=>setSession(data.session));
    const{data:sub}=supabase.auth.onAuthStateChange((_event,sess)=>{
      setSession(sess);
      if(!sess)setDataReady(false);
    });
    return()=>sub.subscription.unsubscribe();
  },[]);

  useEffect(()=>{
    if(session){
      loadAllUserData().then(()=>setDataReady(true)).catch(e=>{console.error(e);setDataReady(true);});
    }
  },[session]);

  // Always show intro first, then gate on auth
  if(!introDone) return <CarbonIntro onDone={()=>setIntroDone(true)}/>;
  if(session===undefined||(!session&&!dataReady&&session!==null)) return <SplashLoading/>;
  if(!session) return <LoginScreen/>;
  if(!dataReady) return <SplashLoading/>;
  return <ForgeAppInner/>;
}

 
